import React, { useEffect, useState } from "react";
import {
  Container,
  Typography,
  Card,
  CardContent,
  Grid,
  CircularProgress,
  Box,
} from "@mui/material";
import axios from "axios";

const CompletedTasksPage = () => {
  const [completedTasks, setCompletedTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get("http://localhost:8000/api/tasks/completed")
      .then((response) => {
        setCompletedTasks(response.data.completed_tasks);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching completed tasks:", error);
        setLoading(false);
      });
  }, []);

  return (
    <Container maxWidth="lg">
      <Typography variant="h4" gutterBottom mt={4}>
        Completed Tasks (Approved / Rejected)
      </Typography>

      {loading ? (
        <Box display="flex" justifyContent="center" mt={4}>
          <CircularProgress />
        </Box>
      ) : completedTasks.length === 0 ? (
        <Typography>No completed tasks found.</Typography>
      ) : (
        <Grid container spacing={2}>
          {completedTasks.map((task) => (
            <Grid item xs={12} sm={6} md={4} key={task.task_id + task.approver_email}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle1" fontWeight="bold">
                    Task #{task.task_id}
                  </Typography>
                  <Typography variant="body1" gutterBottom>
                    {task.task_description}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    Approver: {task.approver_email}
                  </Typography>
                  <Typography
                    variant="body2"
                    color={task.approver_status === "Approved" ? "green" : "red"}
                  >
                    Status: {task.approver_status}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}
    </Container>
  );
};

export default CompletedTasksPage;
